'use client';

import { useState } from 'react';
import { FileText, CheckCircle, AlertCircle } from 'lucide-react';

export default function InscriptionPage() {
  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState({
    // Données du formulaire d'inscription
    inscription: {},
    renseignements: {},
    consentement: {}
  });

  const forms = [
    {
      id: 'inscription',
      title: "Formulaire d'Inscription",
      description: "Formulaire à remplir pour s'inscrire aux formations de Mission Agape",
      file: "/FORMULAIRE A REMPLIR PAR L.doc",
      size: "95 KB"
    },
    {
      id: 'renseignements',
      title: "Fiche de Renseignements",
      description: "Fiche de renseignements personnels et spirituels",
      file: "/renseignement confidentie.doc",
      size: "90 KB"
    },
    {
      id: 'consentement',
      title: "Décharge de Consentement",
      description: "Formulaire d'autorisation pour les activités de l'association",
      file: "/formulaire de decharge de consentement.doc",
      size: "32 KB"
    }
  ];

  const handleFormSubmit = (formId: string, data: any) => {
    setFormData(prev => ({
      ...prev,
      [formId]: data
    }));
    setCurrentStep(prev => Math.min(prev + 1, forms.length - 1));
  };

  const isFormComplete = (formId: string) => {
    return Object.keys(formData[formId as keyof typeof formData] || {}).length > 0;
  };

  return (
    <main className="min-h-screen bg-background py-16">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold text-primary mb-4">
            Inscription aux Formations
          </h1>
          <p className="text-xl text-foreground/80">
            Veuillez remplir tous les formulaires requis pour finaliser votre inscription
          </p>
        </div>

        {/* Progress Steps */}
        <div className="mb-12">
          <div className="flex items-center justify-between relative">
            {forms.map((form, index) => (
              <div key={form.id} className="flex flex-col items-center z-10">
                <div 
                  className={`w-12 h-12 rounded-full flex items-center justify-center ${
                    currentStep >= index 
                      ? 'bg-primary text-white' 
                      : 'bg-gray-200 text-gray-600'
                  }`}
                >
                  {isFormComplete(form.id) ? (
                    <CheckCircle className="w-6 h-6" />
                  ) : (
                    <span>{index + 1}</span>
                  )}
                </div>
                <span className="text-sm mt-2 text-center">{form.title}</span>
              </div>
            ))}
            <div className="absolute top-6 left-0 right-0 h-1 bg-gray-200 -z-10">
              <div 
                className="h-full bg-primary transition-all duration-300"
                style={{
                  width: `${(currentStep / (forms.length - 1)) * 100}%`
                }}
              />
            </div>
          </div>
        </div>

        {/* Form Container */}
        <div className="bg-white dark:bg-card rounded-xl shadow-lg p-6 md:p-8">
          <div className="mb-6">
            <h2 className="text-2xl font-bold text-foreground mb-2">
              {forms[currentStep].title}
            </h2>
            <p className="text-foreground/70">
              {forms[currentStep].description}
            </p>
          </div>

          {/* PDF Viewer / Form */}
          <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 mb-6 min-h-[500px] flex flex-col items-center justify-center">
            <FileText className="w-16 h-16 text-gray-400 mb-4" />
            <p className="text-foreground/70 mb-4">
              Aperçu du formulaire "{forms[currentStep].title}"
            </p>
            <a 
              href={forms[currentStep].file} 
              download
              className="inline-flex items-center px-6 py-3 border border-transparent text-base font-medium rounded-md text-white bg-primary hover:bg-primary/90 transition-colors"
            >
              <Download className="h-5 w-5 mr-2" />
              Télécharger le formulaire
            </a>
          </div>

          {/* Navigation Buttons */}
          <div className="flex justify-between mt-8">
            <button
              onClick={() => setCurrentStep(prev => Math.max(prev - 1, 0))}
              disabled={currentStep === 0}
              className={`px-6 py-2 rounded-md ${
                currentStep === 0 
                  ? 'bg-gray-200 text-gray-500 cursor-not-allowed' 
                  : 'bg-gray-200 hover:bg-gray-300 text-foreground'
              } transition-colors`}
            >
              Précédent
            </button>
            
            {currentStep < forms.length - 1 ? (
              <button
                onClick={() => setCurrentStep(prev => prev + 1)}
                className="px-6 py-2 bg-primary hover:bg-primary/90 text-white rounded-md transition-colors"
              >
                Suivant
              </button>
            ) : (
              <button
                onClick={() => {
                  // Soumettre tous les formulaires
                  console.log('Tous les formulaires soumis :', formData);
                  // Ici, vous pouvez ajouter la logique de soumission
                }}
                className="px-6 py-2 bg-green-600 hover:bg-green-700 text-white rounded-md transition-colors"
              >
                Soumettre l'inscription
              </button>
            )}
          </div>
        </div>

        {/* Help Section */}
        <div className="mt-8 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg flex items-start">
          <AlertCircle className="w-5 h-5 text-blue-600 dark:text-blue-400 mt-0.5 mr-3 flex-shrink-0" />
          <div>
            <h3 className="font-medium text-foreground">Besoin d'aide ?</h3>
            <p className="text-sm text-foreground/70 mt-1">
              Si vous rencontrez des difficultés pour remplir les formulaires, 
              n'hésitez pas à nous contacter à l'adresse 
              <a href="mailto:contact@missionagape.org" className="text-primary hover:underline ml-1">
                contact@missionagape.org
              </a>
            </p>
          </div>
        </div>
      </div>
    </main>
  );
}
